  1	// Command grammar-refresh vendors a tree-sitter grammar into
  2	// internal/sem/grammars/<lang> from its upstream git repository and records
  3	// where it came from in internal/sem/grammars/grammars.json. It is a
  4	// maintainer tool: it needs the network, and its output is committed, so
  5	// building entire-graph never downloads anything.
  6	//
  7	// Usage:
  8	//
  9	//	go run ./cmd/grammar-refresh -lang swift -ref 0.7.4-with-generated-files
 10	//	go run ./cmd/grammar-refresh -lang fsharp -ref <commit> -path fsharp
 11	//	go run ./cmd/grammar-refresh -lang newlang -ref v1.0.0 -url https://github.com/o/tree-sitter-newlang
 12	//
 13	// The ref must contain generated sources (src/parser.c) built for ABI 13-14,
 14	// the range the go-tree-sitter runtime loads. binding.go is never touched, so
 15	// a new language still needs one. A grammar that changes parse results needs
 16	// an IdentityRevision bump (internal/sem/provider.go) in the same commit.
 17	package main
 18	
 19	import (
 20		"flag"
 21		"fmt"
 22		"os"
 23		"os/exec"
 24		"path/filepath"
 25		"strings"
 26	)
 27	
 28	func main() {
 29		var (
 30			lang         = flag.String("lang", "", "grammar directory name under -dir (required)")
 31			ref          = flag.String("ref", "", "tag, branch or full commit to vendor (required)")
 32			url          = flag.String("url", "", "git URL; defaults to the manifest entry")
 33			subdir       = flag.String("path", "", "grammar subdirectory within the repository; defaults to the manifest entry")
 34			manifestPath = flag.String("manifest", "internal/sem/grammars/grammars.json", "path to the grammar manifest")
 35			grammarsDir  = flag.String("dir", "internal/sem/grammars", "directory holding vendored grammars")
 36		)
 37		flag.Parse()
 38		if *lang == "" || *ref == "" {
 39			flag.Usage()
 40			os.Exit(2)
 41		}
 42		if err := refresh(*lang, *ref, *url, *subdir, *manifestPath, *grammarsDir); err != nil {
 43			fmt.Fprintln(os.Stderr, "grammar-refresh:", err)
 44			os.Exit(1)
 45		}
 46	}
 47	
 48	func refresh(lang, ref, url, subdir, manifestPath, grammarsDir string) error {
 49		grammars, err := loadManifest(manifestPath)
 50		if err != nil {
 51			return err
 52		}
 53		var existing Grammar
 54		for _, g := range grammars {
 55			if g.Language == lang {
 56				existing = g
 57			}
 58		}
 59		if url == "" {
 60			url = existing.URL
 61		}
 62		if url == "" {
 63			return fmt.Errorf("%s is not in %s; pass -url", lang, manifestPath)
 64		}
 65		if subdir == "" {
 66			subdir = existing.Path
 67		}
 68	
 69		tmp, err := os.MkdirTemp("", "grammar-refresh-")
 70		if err != nil {
 71			return err
 72		}
 73		defer os.RemoveAll(tmp)
 74		if err := git(tmp, "init", "-q"); err != nil {
 75			return err
 76		}
 77		if err := git(tmp, "fetch", "-q", "--depth", "1", url, ref); err != nil {
 78			return fmt.Errorf("fetch %s %s: %w", url, ref, err)
 79		}
 80		if err := git(tmp, "checkout", "-q", "FETCH_HEAD"); err != nil {
 81			return err
 82		}
 83		revision, err := gitOutput(tmp, "rev-parse", "HEAD")
 84		if err != nil {
 85			return err
 86		}
 87	
 88		files, abi, err := vendor(tmp, subdir, filepath.Join(grammarsDir, lang))
 89		if err != nil {
 90			return err
 91		}
 92		note := ""
 93		if existing.Revision == revision {
 94			note = existing.Note
 95		}
 96		grammars = upsert(grammars, Grammar{
 97			Language:  lang,
 98			URL:       url,
 99			Reference: ref,
100			Revision:  revision,
101			Path:      subdir,
102			Files:     files,
103			ABI:       abi,
104			Note:      note,
105		})
106		if err := saveManifest(manifestPath, grammars); err != nil {
107			return err
108		}
109		fmt.Printf("vendored %s %s (%s, ABI %d) into %s\n", lang, ref, revision[:7], abi, filepath.Join(grammarsDir, lang))
110		fmt.Println("next: bump IdentityRevision in internal/sem/provider.go if parse results change, and run scripts/gen-notices.sh")
111		return nil
112	}
