114	func git(dir string, args ...string) error {
115		cmd := exec.Command("git", args...)
116		cmd.Dir = dir
117		cmd.Stderr = os.Stderr
118		return cmd.Run()
119	}
120	
121	func gitOutput(dir string, args ...string) (string, error) {
122		cmd := exec.Command("git", args...)
123		cmd.Dir = dir
124		cmd.Stderr = os.Stderr
125		out, err := cmd.Output()
126		return strings.TrimSpace(string(out)), err
127	}
  1	package main
  2	
  3	import (
  4		"bytes"
  5		"encoding/json"
  6		"fmt"
  7		"os"
  8		"path/filepath"
  9		"regexp"
 10		"sort"
 11		"strconv"
 12		"strings"
 13	)
 14	
 15	const (
 16		minABI = 13
 17		maxABI = 14
 18	)
 19	
 20	// Grammar is one vendored grammar's origin, as recorded in grammars.json.
 21	type Grammar struct {
 22		Language  string   `json:"language"`
 23		URL       string   `json:"url"`
 24		Reference string   `json:"reference"`
 25		Revision  string   `json:"revision"`
 26		Path      string   `json:"path,omitempty"`
 27		Files     []string `json:"files"`
 28		ABI       int      `json:"abi"`
 29		Note      string   `json:"note,omitempty"`
 30	}
 31	
 32	var languageVersionPattern = regexp.MustCompile(`(?m)^#define LANGUAGE_VERSION (\d+)\s*$`)
 33	
 34	func languageABI(parserC []byte) (int, error) {
 35		m := languageVersionPattern.FindSubmatch(parserC)
 36		if m == nil {
 37			return 0, fmt.Errorf("parser.c has no #define LANGUAGE_VERSION")
 38		}
 39		return strconv.Atoi(string(m[1]))
 40	}
 41	
 42	// vendor copies a generated grammar from repoRoot/subdir into destDir:
 43	// src/parser.c, src/scanner.c when present, src/*.h, src/tree_sitter/*.h and the
 44	// license file (from the grammar directory, else the repository root). Files
 45	// of those kinds already in destDir that the new grammar lacks are removed;
 46	// everything else there, such as binding.go, is left alone. Nothing in destDir
 47	// changes unless the grammar has a parser.c the go-tree-sitter runtime can load.
 48	func vendor(repoRoot, subdir, destDir string) ([]string, int, error) {
 49		grammarRoot := filepath.Join(repoRoot, subdir)
 50		parserC, err := os.ReadFile(filepath.Join(grammarRoot, "src", "parser.c"))
 51		if err != nil {
 52			return nil, 0, fmt.Errorf("%s has no generated src/parser.c (is this a ref with generated files?): %w", filepath.Join(subdir, "src"), err)
 53		}
 54		abi, err := languageABI(parserC)
 55		if err != nil {
 56			return nil, 0, err
 57		}
 58		if abi < minABI || abi > maxABI {
 59			return nil, 0, fmt.Errorf("grammar is ABI %d, but the go-tree-sitter runtime accepts ABI %d-%d; regenerate it with `tree-sitter generate --abi 14` and vendor the result", abi, minABI, maxABI)
 60		}
 61	
 62		sources := map[string]string{"parser.c": filepath.Join(grammarRoot, "src", "parser.c")}
 63		if scanner := filepath.Join(grammarRoot, "src", "scanner.c"); fileExists(scanner) {
 64			sources["scanner.c"] = scanner
 65		}
 66		for _, dir := range []string{"", "tree_sitter/"} {
 67			headers, err := filepath.Glob(filepath.Join(grammarRoot, "src", filepath.FromSlash(dir), "*.h"))
 68			if err != nil {
 69				return nil, 0, err
 70			}
 71			for _, h := range headers {
 72				sources[dir+filepath.Base(h)] = h
 73			}
 74		}
 75		license := findLicense(grammarRoot)
 76		if license == "" {
 77			license = findLicense(repoRoot)
 78		}
 79		if license == "" {
 80			return nil, 0, fmt.Errorf("no LICENSE or COPYING file in %s or the repository root", grammarRoot)
 81		}
 82		sources[filepath.Base(license)] = license
 83	
 84		stale, err := vendoredFiles(destDir)
 85		if err != nil {
 86			return nil, 0, err
 87		}
 88		for _, rel := range stale {
 89			if _, keep := sources[rel]; !keep {
 90				if err := os.Remove(filepath.Join(destDir, filepath.FromSlash(rel))); err != nil {
 91					return nil, 0, err
 92				}
 93			}
 94		}
 95		files := make([]string, 0, len(sources))
 96		for rel, src := range sources {
 97			data, err := os.ReadFile(src)
 98			if err != nil {
 99				return nil, 0, err
100			}
101			dst := filepath.Join(destDir, filepath.FromSlash(rel))
102			if err := os.MkdirAll(filepath.Dir(dst), 0o755); err != nil {
103				return nil, 0, err
104			}
105			if err := os.WriteFile(dst, data, 0o644); err != nil {
106				return nil, 0, err
107			}
108			files = append(files, rel)
109		}
110		sort.Strings(files)
111		return files, abi, nil
112	}
113	
114	func fileExists(path string) bool {
115		info, err := os.Stat(path)
116		return err == nil && !info.IsDir()
117	}
118	
119	func findLicense(dir string) string {
120		entries, err := os.ReadDir(dir)
121		if err != nil {
122			return ""
123		}
124		for _, e := range entries {
125			name := strings.ToUpper(e.Name())
126			if !e.IsDir() && (strings.HasPrefix(name, "LICENSE") || strings.HasPrefix(name, "COPYING")) {
127				return filepath.Join(dir, e.Name())
128			}
129		}
130		return ""
131	}
132	
133	// vendoredFiles lists the files in destDir that vendor manages.
134	func vendoredFiles(destDir string) ([]string, error) {
135		var out []string
136		entries, err := os.ReadDir(destDir)
137		if err != nil {
138			if os.IsNotExist(err) {
139				return nil, nil
140			}
141			return nil, err
142		}
143		for _, e := range entries {
144			name := e.Name()
145			upper := strings.ToUpper(name)
146			switch {
147			case e.IsDir() && name == "tree_sitter":
148				headers, err := filepath.Glob(filepath.Join(destDir, "tree_sitter", "*.h"))
149				if err != nil {
150					return nil, err
151				}
152				for _, h := range headers {
153					out = append(out, "tree_sitter/"+filepath.Base(h))
154				}
155			case name == "parser.c" || name == "scanner.c", !e.IsDir() && strings.HasSuffix(name, ".h"),
156				strings.HasPrefix(upper, "LICENSE"), strings.HasPrefix(upper, "COPYING"):
157				out = append(out, name)
158			}
159		}
160		return out, nil
161	}
162	
163	func loadManifest(path string) ([]Grammar, error) {
164		data, err := os.ReadFile(path)
165		if err != nil {
166			if os.IsNotExist(err) {
167				return nil, nil
168			}
169			return nil, err
170		}
171		var grammars []Grammar
172		if err := json.Unmarshal(data, &grammars); err != nil {
173			return nil, fmt.Errorf("%s: %w", path, err)
174		}
175		return grammars, nil
176	}
177	
178	func saveManifest(path string, grammars []Grammar) error {
179		var buf bytes.Buffer
180		enc := json.NewEncoder(&buf)
181		enc.SetEscapeHTML(false)
182		enc.SetIndent("", "  ")
183		if err := enc.Encode(grammars); err != nil {
184			return err
185		}
186		return os.WriteFile(path, buf.Bytes(), 0o644)
187	}
188	
189	// upsert replaces the entry for g.Language, or inserts it, keeping the
190	// manifest sorted by language.
191	func upsert(grammars []Grammar, g Grammar) []Grammar {
192		i := sort.Search(len(grammars), func(i int) bool { return grammars[i].Language >= g.Language })
193		if i < len(grammars) && grammars[i].Language == g.Language {
194			grammars[i] = g
195			return grammars
196		}
197		grammars = append(grammars, Grammar{})
198		copy(grammars[i+1:], grammars[i:])
199		grammars[i] = g
200		return grammars
201	}

